import java.io.*;import java.util.*;class Result {public static int crabGraphs(int n, int t, List<List<Integer>> edges) {List<Integer>[] adj = new ArrayList[n + 1];for (int i = 1; i <= n; i++) {adj[i] = new ArrayList<Integer>();}for (List<Integer> edge : edges) {int u = edge.get(0);int v = edge.get(1);adj[u].add(v);adj[v].add(u);}int source = 0;int sink = 2 * n + 1;int[][] capacity = new int[sink + 1][sink + 1];for (int i = 1; i <= n; i++) {capacity[source][i] = t;for (int neighbor : adj[i]) {capacity[i][n + neighbor] = 1;}}for (int i = 1; i <= n; i++) {capacity[n + i][sink] = 1;}int flow = 0;while (true) {int[] parent = new int[sink + 1];Arrays.fill(parent, -1);Queue<Integer> q = new LinkedList<Integer>();q.add(source);parent[source] = source;while (!q.isEmpty()) {int u = q.poll();for (int v = 0; v <= sink; v++) {if (parent[v] == -1 && capacity[u][v] > 0) {parent[v] = u;q.add(v);}}}if (parent[sink] == -1) break;flow++;int curr = sink;while (curr != source) {int prev = parent[curr];capacity[prev][curr]--;capacity[curr][prev]++;curr = prev;}}Set<Integer> headsSet = new HashSet<Integer>();Set<Integer> feetSet = new HashSet<Integer>();for (int i = 1; i <= n; i++) {boolean isHead = false;for (int neighbor : adj[i]) {if (capacity[n + neighbor][i] == 1) {isHead = true;break;}}if (isHead) {headsSet.add(i);}if (capacity[sink][n + i] == 1) {feetSet.add(i);}}int headsUsed = headsSet.size();int totalFeet = flow;int intersectionCount = 0;for (int headNode : headsSet) {if (feetSet.contains(headNode)) {intersectionCount++;}}return headsUsed + totalFeet - intersectionCount;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int c = Integer.parseInt(line.trim());while (c-- > 0) {String line2 = br.readLine();if (line2 == null) break;String[] first = line2.trim().split("\\s+");int n = Integer.parseInt(first[0]);int t = Integer.parseInt(first[1]);int m = Integer.parseInt(first[2]);List<List<Integer>> graph = new ArrayList<List<Integer>>();for (int j = 0; j < m; j++) {String[] edge = br.readLine().trim().split("\\s+");List<Integer> e = new ArrayList<Integer>();e.add(Integer.parseInt(edge[0]));e.add(Integer.parseInt(edge[1]));graph.add(e);}System.out.println(Result.crabGraphs(n, t, graph));}br.close();}}